Code examples
A Cox model with explicit Efron ties and reference coding:
proc phreg data=proj.actg;
  class arms(ref="0") / param=ref;          /* 0 = ZDV only */
  model days*cens(0) = arms age wtkg karnof cd40 cd80
                       gender race hemo homo drugs symptom str2
        / ties=efron risklimits;
run;
A macro that fits the same model in each subgroup and collects the hazard ratios for the forest plot:
%macro sub(var=, val=, label=, order=);
  proc phreg data=work.sg(where=(&var=&val));
    model days*cens(0) = treat / ties=efron risklimits;
    ods output ParameterEstimates=_pe;
  run;
  data _pe;
    length subgroup $40;
    set _pe;
    subgroup = "&label";
    order    = &order;
  run;
  proc append base=work.forest data=_pe force; run;
%mend sub;
